def transform(grid):
    g = [row[:] for row in grid]
    n = len(g)
    k = int((n + 1) ** 0.5)
    step = k + 1
    # Each k-by-k motif occupies a cell in a k-by-k array, separated by a blank row/column.
    tiles = [[ [g[r*step+i][c*step+j] for i in range(k)] for j in range(k)]
              for r in range(k) for c in []]  # initialized below
    tiles = [[[[g[r*step+i][c*step+j] for j in range(k)] for i in range(k)]
              for c in range(k)] for r in range(k)]
    occ = [[any(v == 2 for row in tiles[r][c] for v in row) for c in range(k)] for r in range(k)]
    # A solid 3 band masks one row or column of the motif array. Restore slots
    # that continue through all the unmasked rows/columns.
    mask_rows = [r for r in range(k) if all(g[r*step+i][j] == 3 for i in range(k) for j in range(n))]
    mask_cols = [c for c in range(k) if all(g[i][c*step+j] == 3 for j in range(k) for i in range(n))]
    added = []
    if mask_rows:
        mr = mask_rows[0]
        template = next(tiles[r][c] for r in range(k) for c in range(k) if occ[r][c])
        cols = [c for c in range(k) if template[mr][c] == 2]
        for c in cols:
            added.append((mr, c, template))
    elif mask_cols:
        mc = mask_cols[0]
        # Continue objects into the masked column from the outer side when the
        # corresponding diagonal marker is present.
        for r in range(k):
            src = next((tiles[r][c] for c in range(k) if c != mc and occ[r][c]), None)
            if src and r < k and mc < k and src[r][mc] == 2:
                added.append((r, mc, src))
    # Remove the 3 mask, then restore inferred motif tiles.
    for r in range(n):
        for c in range(n):
            if g[r][c] == 3:
                g[r][c] = 0
    for r, c, tile in added:
        for i in range(k):
            for j in range(k):
                g[r*step+i][c*step+j] = tile[i][j]
    # Mark the (row, column) coordinate inside each motif in color 8.
    for r in range(k):
        for c in range(k):
            if any(g[r*step+i][c*step+j] == 2 for i in range(k) for j in range(k)):
                if g[r*step+r][c*step+c] == 2:
                    g[r*step+r][c*step+c] = 8
    return g
